# The sheet's rate for each grade that has one, by grade.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: asof
asof:
  class: net.officefloor.hq.app.history.ValidateViewAsOf
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
  govern: [ readonly-transaction ]
# Set a grade's rate. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: rate
rate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
