import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { counts, useClaimTags, useClaims } from '../claims/useClaims';
import { gradeOn, useHeld, usePeople } from '../people/people.slot';
import { useSheetToday } from '../today/today.slot';
import { useUser } from '../session/useSession';
import { claimDueCents, isBound, rateOn, ratesKey, showHundredths, toHundredths, trimmedSum, useRates, type Rate } from './useRates';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useCapCents, useFloorCents, useLate } from '../access/useAccess';

const GRADES = ['A', 'B', 'C'] as const;
const RATE = /^\d{1,3}(\.\d{1,2})?$/;
const NA = 'n/a';

/** The rate (in hundredths of a percent) in force on the sheet's today for each grade that has one. */
function useRateByGrade(sheetId: string): Map<string, bigint> {
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const byGrade = new Map<string, bigint>();
  if (today === undefined) return byGrade;
  for (const g of GRADES) {
    const r = rateOn(rates.data ?? [], g, today);
    if (r) byGrade.set(g, toHundredths(r.rate));
  }
  return byGrade;
}

/** A person's due-total in cents, held to the sheet's cap: the cap when their figures add up to more (an n/a one is
 *  not capped). Everything that adds up due-totals uses this. */
export function useDueTotals(sheetId: string): Map<number, bigint | null> {
  const sums = useUncappedDueTotals(sheetId);
  const cap = useCapCents(sheetId);
  const totals = new Map<number, bigint | null>();
  for (const [id, sum] of sums) totals.set(id, sum != null && cap != null && sum > cap ? cap : sum);
  return totals;
}

/** A person's excess in cents: how far their figures add up to more than the sheet's cap; 0 otherwise (and when n/a). */
export function useExcesses(sheetId: string): Map<number, bigint> {
  const sums = useUncappedDueTotals(sheetId);
  const cap = useCapCents(sheetId);
  const excess = new Map<number, bigint>();
  for (const [id, sum] of sums) excess.set(id, sum != null && cap != null && sum > cap ? sum - cap : 0n);
  return excess;
}

/** A person's uncapped due-total in cents: their counted claims' already-rounded figures added up (0 with none). Null when
 *  their grade has no rate on the sheet's today, unless a counted settled or stated claim keeps a figure, or a claim has
 *  one at a grade other than today's or dated on or before today (from its own date): then the figures there are, added up. */
function useUncappedDueTotals(sheetId: string): Map<number, bigint | null> {
  const parts = useDueParts(sheetId);
  const totals = new Map<number, bigint | null>();
  for (const [id, part] of parts) totals.set(id, part.total);
  return totals;
}

type Split = { settled: bigint; open: bigint };

/** A person's settled-total and open-total in cents: the figures of their counted SETTLED claims (corrections included), and of
 *  their counted OPEN and PENDING ones, each added up (n/a as 0). Together they make the uncapped due-total. */
export function useSplitTotals(sheetId: string): Map<number, Split> {
  const parts = useDueParts(sheetId);
  const splits = new Map<number, Split>();
  for (const [id, part] of parts) splits.set(id, { settled: part.settled, open: part.open });
  return splits;
}

/** The pieces of each person's uncapped due-total: the total itself (null when n/a) and its settled and open parts. */
function useDueParts(sheetId: string): Map<number, Split & { total: bigint | null }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useRateByGrade(sheetId);
  const todayDate = useSheetToday(sheetId).data?.today;
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const parts = new Map<number, Split & { total: bigint | null }>();
  for (const p of people.data ?? []) {
    const counted = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, held));
    let settled = 0n;
    let open = 0n;
    let kept = false;
    for (const c of counted) {
      const grade = gradeOn(p, c.date);
      const due = claimDueCents(rates.data ?? [], grade, c, floor, late);
      // A figure dated on or before today stands even if its rate has ended since.
      kept ||= c.settledDue != null || (isBound(c) && c.statedDue != null)
        || (due != null && (grade !== p.grade || (todayDate !== undefined && c.date <= todayDate)));
      if (c.status === 'SETTLED') settled += due ?? 0n;
      else open += due ?? 0n;
    }
    parts.set(p.id, { settled, open, total: today.has(p.grade) || kept ? settled + open : null });
  }
  return parts;
}

// The rate form: sets a grade's rate from a date (blank: from the beginning of time) through a to-date
// (blank: with no end; never before the from-date), replacing one
// already set for that grade and date. Every rate is listed under it, with each grade's rate in
// force on the sheet's today.
function RatesPanel({ sheetId }: { sheetId: string; user: string }) {
  const rates = useRates(sheetId);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const today = useSheetToday(sheetId).data?.today;
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (body: { grade: string; rate: string; from: string; to: string }) => {
      if (body.rate.trim() === '') throw new Error('Enter a rate');
      if (!RATE.test(body.rate.trim()) || Number(body.rate) > 100) {
        throw new Error('A rate is a percent, 0.00 to 100.00, with up to two decimals');
      }
      // `by` is the signed-in user the change is recorded against.
      return putJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, { ...body, from: body.from.trim(), to: body.to.trim(), by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
      setPct('');
      setFrom('');
      setTo('');
    },
  });

  const submit = useSubmitOnce(save);
  return (
    <section data-testid="rates-panel">
      <h2>Rates</h2>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ grade, rate: pct, from, to });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            placeholder="0.00"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="rate-form-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="date"
            data-testid="rate-form-to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <p data-testid="rate-form-error" role="alert">
            {save.error.message}
          </p>
        )}
      </form>
      {rates.isError && (
        <p data-testid="rates-error" role="alert">
          {rates.error.message}
        </p>
      )}
      <table data-testid="rate-current-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const r = today === undefined ? undefined : rateOn(rates.data ?? [], g, today);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`rate-current-${g}`}>{r ? showHundredths(toHundredths(r.rate)) : NA}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {(rates.data ?? []).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? ''}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
              <td data-testid="rate-pct">{showHundredths(toHundredths(r.rate))}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueHead() {
  return <th>Due total</th>;
}

// A person's due-total: their counted claims' due figures added up, at most the sheet's cap; n/a when the grade has no rate today and
// no settled or stated claim keeps a figure.
function DueTotalCell({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const total = useDueTotals(sheetId).get(personId);
  return <td data-testid="person-due-total">{total == null ? NA : showHundredths(total)}</td>;
}

function SplitHeads() {
  return (
    <>
      <th>Settled total</th>
      <th>Open total</th>
    </>
  );
}

// A person's settled-total and open-total: their counted SETTLED claims' due, and their counted OPEN and PENDING claims' due, added up.
function SplitCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const split = useSplitTotals(sheetId).get(personId) ?? { settled: 0n, open: 0n };
  return (
    <>
      <td data-testid="person-settled-total">{showHundredths(split.settled)}</td>
      <td data-testid="person-open-total">{showHundredths(split.open)}</td>
    </>
  );
}

function ExcessHead() {
  return <th>Excess</th>;
}

// A person's excess: how far their figures add up to more than the sheet's cap; 0.00 when they do not.
function ExcessCell({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const excess = useExcesses(sheetId).get(personId) ?? 0n;
  return <td data-testid="person-excess">{showHundredths(excess)}</td>;
}

// A claim's due: fixed when it was settled; the bound figure while a statement binds it; otherwise its amount times the rate in force on the claim's
// date of its person's grade on that date; with its late charge on top while it is overdue, then at least the sheet's floor; n/a when no rate of the grade applies then.
function ClaimDue({ sheetId, personId, claim }: { sheetId: string; user: string; personId: number;
  claim: { amount: string; date: string; status: string; settledDue: string | null; stated: boolean; statedDue: string | null;
    dueBy: string; corrects?: string | null; deferred?: boolean } }) {
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const grade = gradeOn(people.data?.find((p) => p.id === personId), claim.date);
  const due = claimDueCents(rates.data ?? [], grade, claim, floor, late);
  return <span data-testid="claim-due">{due == null ? NA : showHundredths(due)}</span>;
}

/** The sheet's due-total: everyone's due-total added up, skipping those that are n/a, and leaving out the single highest
 *  and the single lowest when three or more people have one. */
export function useSheetDueTotal(sheetId: string): bigint {
  const totals = useDueTotals(sheetId);
  return trimmedSum([...totals.values()].filter((t): t is bigint => t != null));
}

// The sheet's due-total, as the rollup shows it.
function DueTotal({ sheetId }: { sheetId: string; user: string }) {
  const sum = useSheetDueTotal(sheetId);
  return (
    <section data-testid="due-rollup">
      <p>
        Due total: <strong data-testid="rollup-due-total">{showHundredths(sum)}</strong>
      </p>
    </section>
  );
}

// The sheet's settled-total and open-total: everyone's added up, untrimmed.
function SplitTotal({ sheetId }: { sheetId: string; user: string }) {
  const splits = [...useSplitTotals(sheetId).values()];
  const settled = splits.reduce((n, s) => n + s.settled, 0n);
  const open = splits.reduce((n, s) => n + s.open, 0n);
  return (
    <section data-testid="split-rollup">
      <p>
        Settled total: <strong data-testid="rollup-settled-total">{showHundredths(settled)}</strong>{' '}
        Open total: <strong data-testid="rollup-open-total">{showHundredths(open)}</strong>
      </p>
    </section>
  );
}

// For every tag ever used on the sheet, its due-total: the due of the counted claims carrying it added up (n/a as 0); a claim
// with two tags counts in both.
function TagTotals({ sheetId }: { sheetId: string; user: string }) {
  const tags = useClaimTags(sheetId);
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const sums = new Map<string, bigint>();
  for (const c of claims.data ?? []) {
    if (c.tags.length === 0 || !counts(c, held)) continue;
    const due = claimDueCents(rates.data ?? [], gradeOn(people.data?.find((p) => p.id === c.personId), c.date), c, floor, late) ?? 0n;
    for (const t of c.tags) sums.set(t, (sums.get(t) ?? 0n) + due);
  }
  return (
    <section data-testid="tag-rollup">
      <h2>Tags</h2>
      <table>
        <thead>
          <tr>
            <th>Tag</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(tags.data ?? []).map((t) => (
            <tr key={t}>
              <td>{t}</td>
              <td data-testid={`tag-${t}-due-total`}>{showHundredths(sums.get(t) ?? 0n)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: RatesPanel }),
  PersonHeads.fill({ order: 20, Component: DueHead }),
  PersonCells.fill({ order: 20, Component: DueTotalCell }),
  PersonHeads.fill({ order: 20.5, Component: SplitHeads }),
  PersonCells.fill({ order: 20.5, Component: SplitCells }),
  PersonHeads.fill({ order: 21, Component: ExcessHead }),
  PersonCells.fill({ order: 21, Component: ExcessCell }),
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  SheetBody.fill({ order: 25, Component: DueTotal }),
  SheetBody.fill({ order: 25.5, Component: SplitTotal }),
  SheetBody.fill({ order: 25.7, Component: TagTotals }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate, in force from its from-date (yyyy-mm-dd; null applies from the beginning of time) through its
 *  to-date (null: with no end). */
export type Rate = { grade: string; rate: string; from: string | null; to: string | null };

/** The key every feature reads the sheet's rates under. */
export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates: each grade may have several, with different from-dates. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/**
 * The grade's rate in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or
 * before it, a rate without a from-date counting as the earliest. Undefined when none applies, or the date is
 * after that one's to-date.
 */
export function rateOn(rates: readonly Rate[], grade: string, date: string): Rate | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    // ISO dates compare as text; no from-date ('') sorts before every date.
    if (found === undefined || (r.from ?? '') > (found.from ?? '')) found = r;
  }
  return found !== undefined && found.to != null && found.to < date ? undefined : found;
}

/** A two-decimal number as a whole count of hundredths ("10.25" -> 1025n, "-1.03" -> -103n), exactly. */
export function toHundredths(text: string): bigint {
  const trimmed = text.trim();
  if (trimmed.startsWith('-')) return -toHundredths(trimmed.slice(1));
  const [whole, frac = ''] = trimmed.split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

/** Hundredths shown with two decimals. */
export function showHundredths(n: bigint): string {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * Due, in cents, on an amount (in cents) at a rate (a percent, in hundredths): amount times rate
 * divided by 100, rounded to two decimals half to even (1.025 -> 1.02, 1.035 -> 1.04), or half up when
 * `halfUp` (1.025 -> 1.03). Rates are never negative; a correction's negative amount rounds the same way as
 * its size (-1.025 -> -1.02, half up -1.03).
 */
export function dueCents(amountCents: bigint, rateHundredths: bigint, halfUp = false): bigint {
  if (amountCents < 0n) return -dueCents(-amountCents, rateHundredths, halfUp);
  // cents * (rate/100 %) / 100 = cents * rateHundredths / 10000
  const exact = amountCents * rateHundredths;
  const whole = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n))) return whole + 1n;
  return whole;
}

/** The late charge's terms as of the sheet's today: its late percent (in hundredths) in force on a date; a grade's
 *  grace (days) in force on a date; and
 *  the sheet's policy date (its today when blank) with the date of each numbered claim, which decide how a claim's
 *  live figures round. */
export type Late = { today: string; pctOn: (date: string) => bigint; graceOn: (grade: string | undefined, date: string) => number; policyDate: string;
  dateOfNumber: ReadonlyMap<string, string> };

/** Whether the claim's live figures round half up: it (or, for a correction, the claim it corrects) is dated before
 *  the sheet's policy date; on or after it they round half to even. Half to even until the sheet's today is known. */
export function roundsHalfUp(late: Late | undefined, claim: { date: string; corrects?: string | null }): boolean {
  if (late === undefined) return false;
  const on = (claim.corrects != null ? late.dateOfNumber.get(claim.corrects) : undefined) ?? claim.date;
  return on < late.policyDate;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** The days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** Whether a claim is a correction: its amount is below 0.00. A correction has no floor and no late charge. */
export function isCorrection(claim: { amount: string }): boolean {
  return claim.amount.trim().startsWith('-') && toHundredths(claim.amount.trim().slice(1)) > 0n;
}

/** Whether a claim is still live and payable: OPEN, or PENDING a steward's approval of its settle. */
export function isOpen(claim: { status: string }): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether the person's last statement binds the claim to its `statedDue`: it was stated, and is not PENDING (a PENDING
 *  claim shows and totals its live figure; rejected back to OPEN, it is bound again). */
export function isBound(claim: { stated: boolean; status?: string }): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** The date a claim's lateness counts from: its due-by plus the grace in force on its date of its person's grade on
 *  that date (none while blank). Overdue once this is before the sheet's today; the 30-day boundaries count from it. */
export function lateFrom(late: Late | undefined, grade: string | undefined, claim: { date: string; dueBy: string }): string {
  const grace = late === undefined ? 0 : late.graceOn(grade, claim.date);
  return grace === 0 ? claim.dueBy : addDays(claim.dueBy, grace);
}

/** A claim's late charge in cents on its figure: for an OPEN (or PENDING) claim past its due-by (the terms-th business day after its date, by the terms fixed when it was added and the sheet's holidays now)
 *  plus its grade's grace (see lateFrom), for every
 *  full 30 days it is overdue, the late percent in force on that boundary date (that date plus 30, 60, 90 ... days) of the figure
 *  plus the charges of the boundaries before it (compounding), each rounded as the claim rounds (roundsHalfUp), the charges added up; otherwise (or for a correction,
 *  or a claim deferred past the sheet's today) 0. */
export function lateCents(late: Late | undefined, claim: { amount: string; date: string; status: string; dueBy: string; corrects?: string | null;
  deferred?: boolean }, figureCents: bigint, grade?: string): bigint {
  if (late === undefined || !isOpen(claim) || isCorrection(claim) || claim.deferred) return 0n;
  const from = lateFrom(late, grade, claim);
  const overdue = daysBetween(from, late.today);
  const periods = overdue > 0 ? BigInt(Math.floor(overdue / 30)) : 0n;
  let charge = 0n;
  for (let n = 1n; n <= periods; n++) {
    const pct = late.pctOn(addDays(from, Number(n) * 30));
    if (pct !== 0n) charge += dueCents(figureCents + charge, pct, roundsHalfUp(late, claim));
  }
  return charge;
}

/** A claim's due figure in cents: fixed when it was settled; while a statement binds it, the figure it was bound to;
 *  otherwise (or while it is PENDING) its amount times its person's grade's rate
 *  in force on the claim's date, rounded half to even (half up when `halfUp`). The floor is not applied here (see
 *  claimDueCents). Null when there is no figure (no rate of the grade then). */
export function claimFigureCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status?: string; settledDue: string | null; stated: boolean; statedDue: string | null },
  halfUp = false): bigint | null {
  if (claim.settledDue != null) return toHundredths(claim.settledDue);
  if (isBound(claim)) return claim.statedDue == null ? null : toHundredths(claim.statedDue);
  const found = grade === undefined ? undefined : rateOn(rates, grade, claim.date);
  if (found === undefined) return null;
  const correction = isCorrection(claim);
  const amount = toHundredths(correction ? claim.amount.trim().slice(1) : claim.amount);
  return dueCents(correction ? -amount : amount, toHundredths(found.rate), halfUp);
}

/** A claim's due in cents: fixed when it was settled; otherwise the greater of the sheet's floor in force on the
 *  claim's date and its figure (claimFigureCents: the rate figure, or the one a statement bound) with its late charge
 *  on top while it is overdue. The charge and the floor are never bound by a statement; a correction has neither.
 *  Null without a figure. */
export function claimDueCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status: string; settledDue: string | null; stated: boolean; statedDue: string | null;
    dueBy: string; corrects?: string | null; deferred?: boolean },
  floorOn: (date: string) => bigint, late: Late | undefined): bigint | null {
  const figure = claimFigureCents(rates, grade, claim, roundsHalfUp(late, claim));
  if (figure == null) return null;
  if (claim.settledDue != null) return figure;
  const due = figure + lateCents(late, claim, figure, grade);
  if (isCorrection(claim)) return due;
  const floor = floorOn(claim.date);
  return due >= floor ? due : floor;
}

/** Figures added up, leaving out the single highest and the single lowest when there are three or more. */
export function trimmedSum(figures: bigint[]): bigint {
  let sum = 0n;
  for (const f of figures) sum += f;
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}

