// The rate preview: how many OPEN and PENDING claims of people on a grade (on the claim's date) would show a different due if a
// candidate rate applied to that grade on every date, and the sum of new due minus current due. A settled or bound claim keeps
// its figure, so it never changes. Nothing is saved.
function RatePreview({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [asked, setAsked] = useState<{ grade: string; rate: string } | null>(null);

  const preview = async () => {
    setAsked(null);
    setError(null);
    const rate = pct.trim();
    if (rate === '') return setError('Enter a rate');
    if (!RATE.test(rate) || Number(rate) > 100) return setError('A rate is a percent, 0.00 to 100.00, with up to two decimals');
    // Re-read what the preview is worked out from, so it reflects the store now.
    await Promise.all([claimsKey(sheetId), peopleKey(sheetId), ratesKey(sheetId)].map((queryKey) => queryClient.invalidateQueries({ queryKey })));
    setAsked({ grade, rate });
  };

  let result: { count: number; diff: bigint } | null = null;
  if (asked !== null) {
    const current = rates.data ?? [];
    const candidate: Rate[] = [...current.filter((r) => r.grade !== asked.grade), { grade: asked.grade, rate: asked.rate, from: null, to: null }];
    let count = 0;
    let diff = 0n;
    for (const c of claims.data ?? []) {
      if (!isOpen(c)) continue;
      const g = gradeOn(people.data?.find((p) => p.id === c.personId), c.date);
      if (g !== asked.grade) continue;
      const was = claimDueCents(current, g, c, floor, late);
      const now = claimDueCents(candidate, g, c, floor, late);
      if (was === now) continue;
      count++;
      diff += (now ?? 0n) - (was ?? 0n);
    }
    result = { count, diff };
  }

  return (
    <form
      data-testid="rate-preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        void preview();
      }}
    >
      <label>
        Preview grade{' '}
        <select
          data-testid="rate-preview-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            setError(null);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Candidate rate %{' '}
        <input
          data-testid="rate-preview-pct"
          inputMode="decimal"
          placeholder="0.00"
          value={pct}
          onChange={(e) => {
            setPct(e.target.value);
            setError(null);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rate-preview">
        Preview
      </button>
      {result !== null && (
        <span>
          {' '}Would change: <strong data-testid="rate-preview-count">{result.count}</strong>{' '}
          Difference: <strong data-testid="rate-preview-diff">{showHundredths(result.diff)}</strong>
        </span>
      )}
      {error !== null && (
        <p data-testid="rate-preview-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

